    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it most effectively uses data from the graph to complete the statement about the level of bonding trust in\nthe UK. The text defines bonding trust as trust within already existing relationships and bridging trust as trust between different groups, often\ninvolving interactions beyond one’s immediate social circle, giving as an example meeting someone at a networking event, a type of event where\npeople would typically make new acquaintances. The graph presents the percentage of UK survey respondents who indicated that they trust\npeople at least somewhat in two categories—people they know personally (bonding trust) and people they are meeting for the first time (bridging\ntrust)—in 2005, 2018, and 2022. According to the graph, the percentage representing bonding trust remained fairly consistent over the period, at\napproximately 96% in 2005, 97% in 2018, and 97% in 2022. By contrast, the percentage representing bridging trust showed more variability, rising\nfrom approximately 46% in 2005 to approximately 55% in 2018 before falling to approximately 53% in 2022.\nChoice B is incorrect because the graph shows that the percentage representing bonding trust didn’t consistently grow from 2005 to 2022; rather,\nit remained largely consistent at approximately 96%, 97%, and 97% in 2005, 2018, and 2022, respectively. Moreover, the graph shows that the\npercentage representing bridging trust didn’t largely decline from 2005 to 2022; rather, it rose from approximately 46% in 2005 to approximately\n55% in 2018 before falling slightly to approximately 53% in 2022. Choice C is incorrect. While the graph indicates that the percentage\nrepresenting bonding trust was approximately the same in 2018 and 2022 (approximately 97%), the graph also shows that bonding trust was\nsubstantially higher than, not lower than, bridging trust in both 2018 (approximately 55%) and 2022 (approximately 53%). Choice D is incorrect.\nWhile the graph does indicate that bonding trust remained higher than bridging trust from 2005 to 2018, the claim that bonding trust declined\nfrom 2005 to 2022 isn’t supported by the graph. The graph shows that the percentage representing bonding trust rose slightly from\napproximately 96% in 2005 to approximately 97% in both 2018 and 2022.",
    "image": "/questions/coeq/sat-coeq-0992bd73.png",
    "passage": "Social scientists distinguish two different categories of social trust: bonding trust and bridging trust. Bonding trust refers to trust within already\nexisting relationships (e.g., within a family), whereas bridging trust refers to trust between different groups, often involving interactions beyond\none’s immediate social circle (e.g., meeting someone at a networking event). In order to evaluate these two aspects of social trust in the United\nKingdom, researchers asked participants in 2005, 2018, and 2022 to rate the level of trust they felt for people they know personally and for\npeople they are meeting for the first time. After analyzing the data from the survey responses, the researchers concluded that the level of\nbonding trust in the UK ______",
