    "explanation": "Choice D is the best answer because it accurately identifies the species with the highest global biomass, the white-tailed deer at approximately\n2.7 million metric tons. The graph shows the global biomass for four wild land mammal species with the highest global biomass. The graph\nindicates that the African bush elephant’s global biomass is about 1.3 million metric tons, the eastern gray kangaroo’s is about 0.6 million metric\ntons, and the wild boar’s is about 1.9 million metric tons. These values are all lower than the global biomass for the white-tailed deer’s\napproximately 2.7 million metric tons. Thus, the white-tailed deer is the species with the highest global biomass.\nChoice A is incorrect because although the graph indicates that the wild boar has a relatively high global biomass of about 1.9 million metric\ntons, it is not the species with the highest value. The white-tailed deer is the species with the highest global biomass at about 2.7 million metric\ntons. Choice B is incorrect because the eastern gray kangaroo has the lowest global biomass value shown on the graph at about 0.6 million\nmetric tons, not the highest global biomass. The white-tailed deer has the highest at about 2.7 million metric tons. Choice C is incorrect because\nalthough the African bush elephant has a substantial global biomass of about 1.3 million metric tons, it is not the species with the highest value\naccording to the graph. The white-tailed deer has the highest global biomass at about 2.7 million metric tons.",
