    "passage": "Huge international exhibitions known as world’s fairs have been held since 1851, but the United States hasn’t hosted one since 1984.\nArchitecture expert Mina Chow argues that this is because some people think the events are too expensive and not popular enough. For\nexample, the 1984 World’s Fair cost $350 million and had only ______",
    "stem": "Which choice most effectively uses data from the table to complete the example?"
