    "explanation": "Choice C is the best answer because it accurately uses data from the graph to complete the statement regarding the research institute’s findings\nabout veteran representation in Congress. The graph shows that the percentage of veterans in both houses of Congress decreased dramatically\nfrom 1973 to 2013. In 1973, the House of Representatives consisted of approximately 74% veterans, and the Senate was made up of\napproximately 79% veterans. By 2013, veteran members of both houses had fallen to approximately 17%–18%. This represents a substantial\ndecrease of more than 50% in each house over this 40-year period.\nChoice A is incorrect because from 2003 to 2023, the House of Representatives did not consistently have a higher percentage of veterans than\nthe Senate did. According to the graph, in 2003 the Senate was made up of approximately 35% veterans, while the House consisted of\napproximately 23% veterans. In 2013, the number of veterans in the Senate was still slightly higher (approximately 18%) than in the House\n(approximately 17%). Only in 2023 did the House have a marginally higher percentage than the Senate. Choice B is incorrect because veterans\ndid not constitute a majority in both houses throughout the entire period shown in the graph from 1953 to 2003. According to the graph, both\nhouses had a majority of veterans in 1953 (approximately 62% in the House and approximately 74% in the Senate) and in 1973 (approximately\n74% in the House and approximately 79% in the Senate), but by 1993 the House had fallen below 50% to approximately 40% veterans. By 2003,\nboth houses were well below 50%. Choice D is incorrect because the percentage of veterans in Congress did not remain consistent from 1993 to\n2023. The graph shows significant changes in the number of members reporting past military service during this period, particularly the\ncontinued decline from 1993 to 2003. In 1993, the House had approximately 40% veterans and the Senate had approximately 63% veterans, but\nby 2003 these percentages had dropped to approximately 23% and 35%, respectively. Furthermore, there was a large gap between the two\nhouses in 1993 that narrowed considerably by 2013, which contradicts the claim that the percentage of veterans across both houses “remained\nfairly consistent” during this period.",
    "image": "/questions/coeq/sat-coeq-3dc911d6.png",
    "passage": "Since the nation’s earliest days, both houses of the United States Congress have counted many military veterans among their elected officials,\nincluding Hiram L. Fong (who served in the US Army Air Force) and Ralph Harold Metcalfe Sr. (who served in the US Army). A research institute\ngathered historical data about congressional members who have reported past military experience and determined that ______",
