    "explanation": "Choice A is the best answer. If female giraffes feed nonoffspring young, that’s direct evidence that \"giraffes may even help each other care for\none another’s newborns.\n\"\nChoice B is incorrect. Confrontations between males doesn’t tell us anything about whether giraffes help each other care for newborns. Choice C\nis incorrect. While this option does mention newborn offspring, it only discusses a mother’s behavior toward her own child, not another giraffe’s\nchild. Choice D is incorrect. Whether or not giraffes are observed communicating with each other doesn’t tell us anything about whether they help\neach other care for newborns.",
    "passage": "Many scientists have believed that giraffes are solitary creatures, preferring to spend their time alone instead of with others. But observations of\ngiraffes and their behavior in recent years has suggested that these animals may be more social than we once thought. For example, scientists\nZoe Muller and Stephen Harris claim that giraffes may even help each other care for one another’s newborns.",
