    "explanation": "Choice A is the best answer because it presents a finding that, if true, would support the researchers’ claim about the diets of jaguars in the\nBrazilian Pantanal. The text notes that jaguars generally eat land-based mammals, but researchers claim that jaguars in the Pantanal can survive\non a diet that includes more fish and aquatic reptiles than mammals. Finding that the remains of aquatic reptiles and fish appear more often in\nthese jaguars’ waste than the remains of mammals do would support the researchers’ claim, since it would suggest that fish and aquatic reptiles\nare a more significant part of the jaguars’ diet than mammals are.\nChoice B is incorrect because finding that a particular aquatic reptile exists in high numbers in the area would not support the researchers’ claim\nabout the jaguars’ diet. The mere presence of many aquatic reptiles nearby does not mean that the jaguars eat those reptiles, let alone survive on\nmore aquatic reptiles and fish than mammals. Choice C is incorrect. Although finding that aquatic reptiles and fish can provide nutrients that\nland mammals typically do not provide could help explain why some animals eat those reptiles and fish, it would not indicate whether the jaguars\nin particular eat those reptiles and fish and thus would not support the researchers’ claim. Choice D is incorrect because finding that when\npreying on mammals, jaguars prefer semiaquatic mammals, such as capybaras, would be irrelevant to the researchers’ claim that the jaguars\ncan survive on a diet of more fish and aquatic reptiles than mammals. The type of mammals the jaguars tend to eat does not indicate anything\nabout whether fish and aquatic reptiles are part of the jaguars’ diet.",
    "passage": "Biologists have generally believed that the diet of jaguars consists mostly of land-based mammals, but researchers studying a population of\njaguars living in the Brazilian Pantanal, a tropical wetland, claim that jaguars can survive on a diet of more fish and aquatic reptiles than\nmammals.",
