    "explanation": "Choice B is the best answer because it presents a quotation that effectively illustrates the claim that the speaker in the poem praises the person\nwho built the fire. In the quotation, the speaker explicitly refers to the builder of the fire—the one “who brought the first wood and coal / To start\nthe Fire”—and offers praise, stating that this person “did his part well.\n”\nChoice A is incorrect. Although the quotation describes seeing people working with shovels and ashes, which can be associated with tending a\nfire, it doesn’t mention the building of the fire or single out any person for praise. Choice C is incorrect. Although the quotation refers to the fire, it\ndescribes the fire dying when left alone, not the star ting of the fire or the person who built it. Choice D is incorrect because the quotation makes\nno reference to the fire and doesn’t praise anyone; it simply states that people got into bed contentedly in nightcaps.",
    "passage": "“Banking Coal” is a 1922 poem by Jean Toomer. The poem describes a fire being lit and maintained. In the poem, the speaker praises the person\nwho built the fire: ______",
