    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it most effectively uses data from the table to complete the text. The text discusses self-employed workers\nin the US, and the table shows the US incorporated and unincorporated self-employment rates in four occupational fields in 2015. According to\nthe table, the incorporated self-employment rate was 8.9% for the management, business, and financial services occupational field, which is\nhigher than the incorporated self-employment rate shown for any other occupational field.\nChoice A is incorrect because according to the table, the incorporated self-employment rate was 5.8% for the sales and related occupational\nfield, which is lower than the 8.9% for the management, business, and financial services occupational field. Choice B is incorrect because\naccording to the table, the incorporated self-employment rate was 2.7% for the installation, maintenance, and repair occupational field, which is\nlower than the 8.9% for the management, business, and financial services occupational field. Choice C is incorrect because according to the\ntable, the incorporated self-employment rate was 4.4% for the construction and resource extraction occupational field, which is lower than the\n8.9% for the management, business, and financial services occupational field.",
    "image": "/questions/coeq/sat-coeq-0ec15b5a.png",
    "passage": "Self-employed workers—individuals who are not employees of other individuals or businesses but instead earn their income as business owners,\nindependent contractors, or freelance workers—make up an important part of the US labor force. In order to receive legal and tax benefits\nenjoyed by corporations, self-employed individuals may choose to incorporate their business. A 2015 survey of incorporated and unincorporated\nself-employment rates in four occupational fields showed that the highest incorporated self-employment rate occurred among people working in\n______",
    "stem": "Which choice most effectively uses data from the table to complete the text?"
