    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it best describes data from the graph that support the biologists’ claim. The text accompanying the graph\ndescribes the efforts of the California Condor Recovery Program, which is working to protect the condor from extinction. The program captured\nsome condors in 1987 in order to breed them and has been reintroducing captive birds into the wild since 1992. Many biologists claim the\nprogram has been a success, as the text explains, and it is reasonable to infer that an indication of the program’s success would be an increase\nin the wild condor population compared to the captive condor population. The graph shows the wild and captive condor populations in California\nbetween 2014 and 2020. In 2014 there were slightly more than 200 wild condors in California, but by 2020 there were more than 300. Meanwhile,\nover the same period the captive condor population remained under 200. Thus, the biologists’ claim about the program’s success is supported by\ndata from the graph showing that the number of wild California condors increased overall from 2014 to 2020 and exceeded the number of those\nliving in captivity.\nChoice A is incorrect because it does not accurately describe data from the graph. The number of captive California condors did not steadily\ndecrease between 2014 and 2020: rather, it increased slightly during some years and decreased slightly during others, generally remaining at\nslightly less than 200. Choice B is incorrect. Even though the graph does show a slight decrease in both the captive and wild condor populations\nfrom 2019 to 2020, such a decrease during a particular year would not demonstrate the program’s success. Choice C is incorrect because it does\nnot accurately describe data from the graph. The difference between the number of captive and wild California condors did not remain relatively\nsteady between 2014 and 2017. While the number of captive condors remained roughly the same during that period, the number of wild condors\nincreased, so the difference between the number of captive and wild condors increased as well.",
