    "passage": "The California Condor Recovery Program is working to protect this large, rare American vulture from extinction. The program captured 27 wild\ncondors in 1987 in order to protect and breed them. Captive birds have been reintroduced into the wild since 1992. Although the California\ncondor is still a rare species, many biologists claim that the program has been reasonably successful.",
    "stem": "Which choice best describes data from the graph that support the biologists’ claim?"
