    "correctAnswer": "A",
    "explanation": "Choice A is the best answer. The claim is about which fish were collected more in winter than in other seasons. By comparing the number of\ncommon silver-biddy and milkfish collected in each season, we can see that more of these fish were collected in winter than in any other season.\nChoice B is incorrect. The claim is about which fish were collected more in winter than in other seasons. This statement compares collections\nacross the three species of fish, rather than comparing collections of individual types of fish across seasons. Choice C is incorrect. The claim is\nabout which fish were collected more in winter than in other seasons. This statement is about spring, rather than winter. Choice D is incorrect.\nThe claim is about which fish were collected more in winter than in other seasons. This statement is about fall, rather than winter, fish\ncollections.",
    "image": "/questions/coeq/sat-coeq-37a49687.png",
    "passage": "Mangroves are trees or bushes that grow on the coastlines of seas and rivers. Areas with mangroves are great places for young fish since they\nhelp keep these fish fed and protected while they grow. To study the importance of mangroves to young fish, researchers Mohamed A.Abu El-\nRegal and Nesreen K. Ibrahim collected and identified young fish from three different mangrove sites in the Egyptian Red Sea. They collected fish\nin the winter, spring, and autumn of 2010, collecting a total of 269 fish from 21 different species. For some species, more fish were collected in\nthe winter than the other two seasons, for instance: ______",
    "stem": "Which choice most effectively uses the data in the graph to complete the example?"
