    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it most effectively uses data from the table to complete the text, providing an example that illustrates that\nthe annual increases in international tourism revenue in 2017 and 2018 weren’t universal. The table shows the annual spending by international\ntourists (which indicates annual international tourism revenue) in 2016–2018 in four Asian countries. According to the table, annual spending by\ninternational tourists in South Korea was $21.0 billion in 2016 and then decreased to $17.2 billion in 2017. This decrease shows that not all of\nthe countries included in the table saw increases in annual international tourism revenue in 2017.\nChoice A is incorrect because the table doesn’t provide any data regarding revenue from tourism by residents of those countries. Even if that\ndata were provided, it wouldn’t be relevant to the claim that the trend of annual increases in international tourism revenue in 2017 and 2018 was\nnot universal. Choice B is incorrect because the data in the table do not support the statement that Japan’s international tourism revenue was\nhigher in 2016 than it was in 2018: the table indicates that Japan’s annual international tourism revenue was $33.5 billion in 2016, which is less\nthan Japan’s annual international tourism revenue of $45.3 billion in 2018. Choice D is incorrect. Although the table does indicate that Thailand’s\nrevenue from international tourism was higher than that of the other three Asian countries in 2016, 2017, and 2018, this information has no direct\nbearing on the text’s claim that not all the Asian countries represented in the table saw an increase in revenue from international tourism.",
