    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it presents a finding that, if true, would most strongly support the claim in the underlined sentence. The text\nbegins by explaining that the por trayal of Mexican American culture in Sandra Cisneros’s The House on Mango Street inspired later authors to\nexplore their own heritage. Noting that Cisneros’s novella was also influential for its depiction of a formative year in a female character’s youth,\nthe text then claims that this depiction inspired other Latina authors to use fiction to explore their own experiences of youth. Since this claim\naddresses how Cisneros encouraged Latina authors specifically to portray their youthful experiences, it would be directly supported by such\nauthors stating that her novella influenced them to write about their own adolescence, or the transitional period between childhood and\nadulthood.\nChoice B is incorrect. The text states that with its por trayal of Mexican American culture, The House on Mango Street inspired later authors to\nexplore their own heritage, and since this statement isn’t limited to only Latina authors, it can be inferred that authors who aren’t Latina were also\nlikely influenced by the novella. But because the claim in the underlined sentence concerns the novella’s influence on Latina authors specifically,\nthe finding that the book also influenced authors who weren’t Latina would fail to provide support for the claim. Choice C is incorrect because the\nfinding that The House on Mango Street has sold millions of copies and is widely read among students in the US doesn’t relate directly to the\ntext’s claim that the novella has influenced Latina authors specifically. Choice D is incorrect. While comparisons of new novels about young\nLatina characters by Latina authors to Cisneros’s The House on Mango Street would likely be founded on similarities between those novels and\nCisneros’s novella, such similarities wouldn’t necessarily be evidence of the novella’s influence; such similarities might arise if Cisneros and\nyounger Latina authors alike depicted certain basic cultural and historical features of their communities. Testimony from younger Latina authors\nabout how The House on Mango Street had inspired them would be far more persuasive evidence of the novella’s influence.",
    "passage": "Sandra Cisneros’s 1984 novella The House on Mango Street made a lasting impact on US literature. Its depiction of Mexican American culture\ninspired later authors to examine their own heritage within their fictional works. Also influential was the book’s por trayal of the main character,\nEsperanza, during a pivotal year of her youth. This insightful depiction of a preteen girl encouraged authors who, like Cisneros herself, are Latina\nto use fictional works to examine experiences from their own youth.",
    "stem": "Which statement, if true, would most strongly support the claim in the underlined sentence?"
