    "explanation": "Choice B is the best answer because it uses data from the graph to effectively complete the statement regarding what the student notices about\nthe number of jobs in computer services in 2010. The graph shows that in 2010, the number of computer services jobs was approximately 6,000,\nwhich is the same approximate number of jobs in engineering services. Additionally, the graph shows that in 2019, the number of jobs in\ntechnical consulting services and the number of jobs in computer services were about the same, at approximately 5,000.\nChoice A is incorrect. While the graph shows that in 2010 the number of computer services jobs (about 6,000) was higher than the number of\ntechnical consulting services jobs (about 4,000), in 2019 the number of computer services jobs (about 5,000) was not about the same as the\nnumber of engineering services jobs (about 6,000). Choice C is incorrect because according to the graph, the number of jobs in computer\nservices was lower than the number of jobs in engineering services in 2019, not 2010. Additionally, the graph shows that in 2019, the number of\ncomputer services jobs (about 5,000) was not higher than the number of jobs in engineering services (about 6,000). Choice D is incorrect\nbecause the graph shows that the number of computer services jobs was about the same as the number of technical consulting services jobs in\n2019, not 2010. This also means the number of computer services jobs could not have been lower than the technical consulting services jobs in\n2019 if they were about the same.",
    "image": "/questions/coeq/sat-coeq-b074cc05.png",
