    "explanation": "Choice A is the best answer because it uses data from the table to effectively support the claim that book genres that typically require the reader\nto start at the beginning of the story and read straight through are more commercially successful as e-books than other genres. For each of three\nyears, the table presents four book genres and the percentage of total sales for each genre in e-book format. Cookbooks, a nonfiction genre, do\nnot require the reader to read straight through. According to the table, 10.5 percent of total cookbook sales in 2016 were in the e-book format.\nThe 2016 percentage of e-book sales was 36.7 percent in the science fiction and fantasy genre, which are typically stories read straight through\nfrom start to finish. The higher percentage of total sales of the story-based e-books in 2016 supports the claim in the text.\nChoice B is incorrect because it compares the e-book sales of romance books in 2006 to those in 2016. Romance books are meant to be read\nstraight through from start to finish. The text claims that books that are not stories and do not require reading straight through are not as\ncommercially successful in e-book format as those that do. As this choice is only comparing e-book sales for one genre, it does not support the\nclaim. Choice C is incorrect because both science fiction and fantasy and romance novels are fiction books meant to be read straight through\nfrom beginning to end. The text claims that books that are not stories and do not require reading straight through are less commercially\nsuccessful in e-book format than those that do. As this choice does not compare e-book sales of story genres to e-book sales in genres that are\nnot stories, it does not support the claim. Choice D is incorrect. Although the data in the table show that the travel guide e-books made up a\ngreater percentage of total sales in 2016 than in 2011, this doesn’t illustrate the claim in the text that e-books in nonfiction genres not meant to\nbe read straight through are less commercially successful. The claim cannot be supported without comparing the percentage of e-book sales\nbetween fiction and nonfiction book genres from the table.",
