    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it presents a finding that, if true, would challenge the assumption that many ecologists have made about\nthe connection between the building of domed nests and geographic range in songbirds. The text says that many ecologists have assumed that\nsince domed nests provide protection from weather conditions, songbird species that build such nests should be able to have larger geographic\nranges than songbird species that build open nests do. If Medina and her colleagues found that species that build open nests tend to have larger\ngeographic ranges than species that build domed nests do, their finding would show the opposite of what the ecologists have assumed. It would\ntherefore challenge the ecologists’ assumption.\nChoice A is incorrect because nothing in the text suggests that there’s a relationship between songbird species’ extinction rates and their\ngeographic ranges. The finding that species that build open nests tend to have higher extinction rates than species that build domed nests do\nwould therefore have no clear bearing on the ecologists’ assumption that domed nests allow species that build them to have larger geographic\nranges than those of species that build open nests. Choice B is incorrect because nothing in the text suggests that there’s a relationship between\nsongbird species’ sizes and their geographic ranges. The finding that species that build open nests tend to be smaller in size than species that\nbuild domed nests are would therefore have no clear bearing on the ecologists’ assumption that domed nests allow species that build them to\nhave larger geographic ranges than those of species that build open nests. Choice C is incorrect because although the text indicates that many\necologists have assumed that there’s a connection between how songbird species build their nests and the species’ geographic ranges, the text\nsays that this assumption is based on the shape of the nests—that is, whether the nests are domed or open—not the number of materials used.\nThe finding that species that build open nests tend to use fewer materials to build their nests than species that build domed nests do would\ntherefore have no clear bearing on the ecologists’ assumption that domed nests allow species that build them to have larger geographic ranges\nthan those of species that build open nests.",
    "passage": "Although most songbirds build open, cupped nests, some species build domed nests with roofs that provide much more protection. Many\necologists have assumed that domed nests would provide protection from weather conditions and thus would allow species that build them to\nhave larger geographic ranges than species that build open nests do. To evaluate this assumption, a research team led by evolutionary biologist\nIliana Medina analyzed data for over 3,000 species of songbirds.",
    "stem": "Which finding from Medina and her colleagues’ study, if true, would most directly challenge the assumption in the underlined sentence?"
