    "explanation": "Choice D is the best answer because it presents a finding that, if true, would support Gardner and colleagues’ conclusion that segments of the\nMissouri River flowing into lakes tend to carry more sediment than do segments of the river flowing out of lakes. The text says that rivers appear\nyellow when they contain a lot of sediment and appear red when they contain a lot of algae. It goes on to explain that Gardner and colleagues\nmeasured the wavelengths of light for different segments of rivers in the United States and classified those wavelength measurements into\ncolors: red for wavelengths of 495 nanometers and below, blue for wavelengths between 495 and 560 nanometers, and yellow for wavelengths\nof 560 nanometers and above. Combined with the earlier information about river colors, this suggests that rivers rich in sediment will have\nwavelengths of 560 nanometers and above (since such rivers appear yellow). If researchers found that Missouri River segments flowing into\nlakes tend to have wavelengths above 560 nanometers and segments flowing out of lakes tend to have wavelengths below 560 nanometers, this\nfinding would support Gardner and colleagues’ conclusion, since it would suggest that the river tends to carry more sediment when it flows into\nlakes than when it flows out of lakes.\nChoice A is incorrect because finding that sections of the Missouri River with high chlorophyll-a levels have wavelengths between 490 and 560\nnanometers would be irrelevant to the researchers’ conclusion that segments of the river flowing into lakes are richer in sediment than are\nsegments of the river flowing out of lakes. This finding would not indicate anything about segments flowing into or out of lakes. Choice B is\nincorrect because finding that lakes through which the Missouri River passes have higher wavelengths near their shores than in the center would\nnot support the researchers’ conclusion that segments of the river flowing into lakes have more sediment than segments flowing out of lakes.\nThis finding would suggest only that there is more sediment around the edges of lakes than in their centers, which does not have any direct\nbearing on the researchers’ conclusion about river segments flowing into and out of lakes. Choice C is incorrect because finding that most\nsegments of the Missouri River have wavelengths significantly higher than 560 nanometers would suggest that most segments of the river are\nhigh in sediment, not that segments flowing into lakes are higher in sediment than segments flowing out of lakes. Only a comparison of river\nsegments flowing into lakes with segments flowing out of lakes can support the researchers’ conclusion.",
    "passage": "Rivers rich in sediment appear yellow, while increases in red algae make rivers appear red. To track things like the sediment or algae content of\nlarge US rivers, John R. Gardner and colleagues used satellite data to determine the dominant visible wavelengths of light measured for various\nsegments of these rivers. The researchers classified wavelengths of 495 nanometers (nm) and below as red, wavelengths between 495 and 560\nnm as blue, and wavelengths of 560 nm and above as yellow. The researchers concluded that for the Missouri River, segments flowing into lakes\ntend to carry more sediment than those flowing out of lakes.",
