    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it most effectively uses data from the table to support the underlined claim. The text indicates that Swahili\nis the first language of up to 15 million people worldwide. The text goes on to claim, in the underlined portion, that even in countries where nearly\neveryone speaks Swahili, many of the language’s speakers don’t have Swahili as their first language. The table indicates that 61 million people in\nTanzania, which amounts to 100 percent of the population, speak Swahili. If 61 million people in Tanzania speak Swahili, but only 15 million\npeople worldwide have Swahili as their first language, that means there are many people in Tanzania who speak Swahili as a language other than\ntheir first language. This information about Swahili speakers in Tanzania therefore supports the claim that many Swahili speakers in countries\nwhere nearly everyone speaks Swahili speak it as a language other than their first language (such as their second, third, or fourth language).\nChoice B is incorrect because it doesn’t accurately describe information in the table. According to the table, Tanzania has 61 million Swahili\nspeakers, not at most 15 million Swahili speakers. Additionally, the table indicates that 100 percent of Tanzania’s population speak Swahili, which\nmeans that the number of Swahili speakers in the country and the country’s total population should be the same, not that they should differ by\nsuch a large amount. Choice C is incorrect because there’s no information in the table or the text that indicates where people who speak Swahili\nas their first language live. Although Kenya’s total population can be inferred from the table—if Kenya has 55 million Swahili speakers and 100%\nof Kenya’s population speak Swahili, then Kenya must have a population of 55 million people—nothing suggests that all the people who speak\nSwahili as their first language live in a single country, let alone that they all live in Kenya. Choice D is incorrect. Although the table does indicate\nthat 100 percent of Kenya’s population and 25 percent of the Democratic Republic of the Congo’s population speak Swahili, this comparison is\nirrelevant to the claim that Swahili isn’t the first language of many of its speakers even in countries where almost everyone speaks Swahili. On its\nown, a difference in the proportions of the population who speak Swahili cannot reveal whether those Swahili speakers have Swahili as their first\nlanguage or a subsequent language.",
    "image": "/questions/coeq/sat-coeq-01c1d9ee.png",
    "passage": "Which choice most effectively uses data from the table to support the underlined claim?",
    "stem": "Which choice most effectively uses data from the graph to complete the text?"
