    "explanation": "Choice A is the best answer. The student concluded that country-specific factors influence changes to median age of first marriage. This choice\ndescribes a time period when the rate of change differed between countries, suggesting that country-specific factors may have played a role in\nthese changes.\nChoice B is incorrect. The student concluded that country-specific factors influence changes to median age of first marriage. However, this\nchoice doesn’t provide any contrasts between countries and thus doesn’t support the idea of country-specific factors influencing median age of\nfirst marriage. Choice C is incorrect. The students’ conclusion is about changes that occurred during the 20th century. This choice provides\nbroad information about the century as a whole, so it doesn’t give insight into how median age at first marriage changed over time. Choice D is\nincorrect. This choice misreads the graph. The median age of first marriage was consistently higher for men than for women in the United States\nduring the time period depicted.",
    "image": "/questions/coeq/sat-coeq-01f19bf3.png",
    "passage": "A sociology student is reading an essay on the median age of first marriage in Western countries throughout the twentieth century. The author of\nthe essay cites factors common to these countries that the author believes caused an increase in the median age of first marriage, such as new\ntechnologies that shortened the time needed for domestic chores, making two-person households less necessary and living alone more viable.\nThe student asserts that beyond these factors there must be additional ones specific to particular Western countries that influenced the increase\nof age at first marriage.",
