    "correctAnswer": "B",
    "explanation": "Choice B is the best answer because it describes data from the graph that complete the text’s discussion of lizard species’ use of maximal\nspeed when escaping predators. According to the text, moving at maximal speed (the highest speed possible) requires so much energy that it is\nnot always an effective strategy for animals, even when they are escaping predators. The graph displays data on the average percent of maximal\nspeed used by lizard species while either escaping predators or pursuing prey. The graph categorizes the data for both pursuing and escaping by\nthe number of species using 30%–39% of maximal speed, 40%–49% of maximal speed, 50%–59% of maximal speed, 60%–69% of maximal\nspeed, 70%–79% of maximal speed, 80%–89% of maximal speed, and 90%–100% of maximal speed, respectively. In the graph, there is at least\none species in each of the following percent categories for maximal speed while escaping predators: 50%–59%, 60%–69%, 70%–79%, and 80%–\n89%. Thus, the data in the graph show that multiple lizard species move at an average of less than 90% of their maximal speed while escaping\npredation.\nChoice A is incorrect because the data in the graph isn’t organized in such a way that a comparison of the percentage of maximal speed used\nwhen escaping predation with the percentage used when pursuing prey is possible at the level of individual species. Choice C is incorrect. It is\ntrue that in the graph, the percent category with the largest number of species using maximal speed while escaping predators is 90%–100% (8\nspecies total). However, these data don’t complete the text, which is concerned instead with how animals are discouraged from using maximal\nspeed even when escaping predators because of the amount of energy required to use it. Choice D is incorrect because these data from the\ngraph pertain to maximal speed while pursuing prey and therefore don’t complete the text’s discussion of lizard species’ use of maximal speed\nwhen escaping predators.",
    "image": "/questions/coeq/sat-coeq-1281dfd5.png",
    "passage": "It may seem that the optimal strategy for an animal pursuing prey or escaping predators is to move at maximal speed, but the energy expense of\nexploiting full speed capacity can disfavor such a strategy even in escape contexts, as evidenced by the fact that ______",
