    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it most effectively illustrates the claim that Mar tí argues that a society’s spiritual well-being depends on the\ncharacter of its literary culture. In the quotation, Mar tí asserts that poetry is “more necessary to a people than industry itself” and that it has the\npower to provide people with “faith and vigor.\n” He also adds that literature gives people “the desire and strength for life.\n” Therefore, this quotation\nshows that Mar tí believes that literature is a societal necessity because it uplifts people and nourishes their spiritual well-being.\nChoice B is incorrect. Although this quotation emphasizes the importance of literature, it focuses on how the nature of a society is reflected in\nthat society’s literature rather than on literature’s value for people’s spiritual well-being. Choice C is incorrect. Although this quotation involves an\nelement of spirituality, it doesn’t discuss literature. The quotation instead focuses on humanity’s actions. Choice D is incorrect because this\nquotation mainly focuses on the importance of Walt Whitman rather than on the value of literature in general.",
    "passage": "“The Poet Walt Whitman” is an 1887 essay by José Mar tí, a Cuban author and political activist, originally written in Spanish. In the essay, Mar tí\nexplores the value of literature, arguing that a society’s spiritual well-being depends on the character of its literary culture: ______",
