    "passage": "Matthew D. Rocklage and team examined whether consumer ratings of movies can predict box office success. The team considered both\nnumeric star ratings and written reviews in their research. To analyze the written reviews, the team measured the emotionality—the degree to\nwhich a written review expresses an emotional reaction—of user reviews on a movie rating website, assigning each review an emotionality score.\nAfter reviewing this research, a student argues that the emotionality of movie reviews is unrelated to a movie’s success at the box office.",
