    "explanation": "Choice D is the best answer because it provides a quotation that would most directly support the student’s claim that the temple’s users were\naware of how materials used in the temple affected sound and deliberately applied that knowledge to shape the sonic experience of people in\nthe space. The quotation indicates that curtains would, at times, be installed specifically “to minimize reverberation and confine the sound,\n”\nthereby illustrating that the users of the temple had knowledge of the acoustic properties of materials within the temple (how curtains dampen\nsound) and employed this knowledge to affect the experience of sound within the space.\nChoice A is incorrect. Although the quotation describes a feature of the temple’s structure (the high ceiling), it makes no mention of the materials\nused, the materials’ acoustic properties, or temple users’ awareness of how materials impact sound quality. Choice B is incorrect because it\ndoesn’t address any materials that were used in the temple, let alone their acoustic properties or temple users’ awareness of how materials\nimpact sound quality. Choice C is incorrect because it doesn’t address any materials that were used in the temple, let alone their acoustic\nproperties or temple users’ awareness of how materials impact sound quality.",
    "passage": "The interiors of many temples in the ancient Middle East needed to satisfy a precise set of acoustic demands: the sounds of chants and hymns\nshould travel with clarity, while profound silences should be fully felt and appreciated. In a research paper, a student claims that the users of one\nsuch temple were aware of how the materials that were used within the structure could affect sound quality and that they deliberately applied\nthis knowledge to influence how sound was experienced in the space.",
    "stem": "Which quotation from a work by a historian would most directly support the student’s claim?"
