    "image": "/questions/coeq/sat-coeq-2c06139b.png",
    "passage": "Ecologist Veronika Bókony and colleagues investigated within-species competition among common toads (Bufo bufo), a species that secretes\nvarious unpleasant-tasting toxins called bufadienolides in response to threats. The researchers tested B. bufo tadpoles’ responses to different\nlevels of competition by creating ponds with different tadpole population densities but a fixed amount of food. Based on analysis of the tadpoles\nafter three weeks, the researchers concluded that increased competition drove bufadienolide production at the expense of growth.",
