    "correctAnswer": "A",
    "explanation": "Choice A is the best answer. The table provides evidence that the words for corn in the Cherokee and Muskogean languages appear unrelated to\nthose in Caddo language, which is described as closely related to the Totozoquean language family. This supports the claim that corn cultivation\nspread across the Southeast without necessarily spreading Totozoquean vocabulary along with it.\nChoice B is incorrect. This choice emphasizes the diversity of Southeastern languages in general, but we’re specifically looking for information\nabout words associated with corn. Choice C is incorrect. This choice shows how words for corn can change and evolve, but we’re looking for an\nexample that shows how some words for corn can be completely unrelated. Choice D is incorrect. This choice shows words for corn that share a\ncommon root, but we’re looking for an example that shows how some words for corn can be unrelated.",
    "image": "/questions/coeq/sat-coeq-35ec767c.png",
    "passage": "In Caddo, a language from what is now the US Southeast, vocabulary pertaining to corn cultivation resembles equivalent vocabulary in the\nTotozoquean language family in Mexico. This resemblance is perhaps attributable to cultural contact: such words could have entered Caddo\nthrough the intermediary of the neighboring but unrelated Chitimacha language, concurrent with the dissemination of corn itself from Mexico\ninto the Southeast after 700 CE. That the vocabulary pertaining to domestic crops accompanies them as they diffuse into new regions is an\nestablished phenomenon globally. Crops may also be decoupled from vocabulary altogether: corn cultivation became ubiquitous among the\nSoutheastern tribes, yet ______",
    "stem": "Which choice most effectively uses data from the table to complete the statement?"
