    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it illustrates the student’s claim about some historians viewing Lumumba primarily as a symbol. This\nquotation argues that Lumumba “warrants” (or deserves) “scholarly attention” as a symbol and not for his “practical accomplishments”—that is,\nhis actions as prime minister—which “can be passed over quickly,\n” or dismissed as being of comparatively little importance. Thus, the quotation\nexpresses the view that the student criticizes some historians for holding.\nChoice A is incorrect. Although this quotation touches on the difficulty of evaluating Lumumba’s legacy, it doesn’t address how historians of\nmodern African politics view him as a symbol. Choice B is incorrect. While this quotation mentions Lumumba’s political beliefs, it doesn’t discuss\nhistorians viewing him as a symbol. Choice D is incorrect. This quotation touches on Lumumba’s vision for his country, but it doesn’t discuss\nhistorians viewing him as a symbol.",
    "passage": "In a research paper, a student criticizes some historians of modern African politics, claiming that they have evaluated Patrice Lumumba, the first\nprime minister of what is now the Democratic Republic of the Congo, primarily as a symbol rather than in terms of his actions.",
    "stem": "Which quotation from a work by a historian would best illustrate the student’s claim?"
