    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it presents data from the table that most effectively complete the statement about the rates at which\nemployment shifted in France and the United States. The text states that over the last two hundred years employment in the agricultural sector\nhas declined while employment in the service sector has risen in both France and the US, and the data from the table reflect these trends. The\ntext asserts, however, that the transition from agriculture to services “happened at very different rates in the two countries.\n” This assertion is best\nsupported by a comparison of data from 1900 and 1950: the table shows that in those years, employment in agriculture went from 43% to 32% in\nFrance (a decline of 11 percentage points) and from 41% to 14% in the US (a decline of 27 percentage points), and that employment in services\nwent from 28% to 35% in France (an increase of 7 percentage points) and from 31% to 53% in the US (an increase of 22 percentage points). In\nother words, the rate of change was greater in the US than in France for both sectors.\nChoice B is incorrect because comparing the data for 1800 and 2012 would suggest a similar rate of change in the two countries, not very\ndifferent rates: employment in agriculture went from 64% in 1800 to 3% in 2012 in France, which is close to the change from 68% in 1800 to 2% in\n2012 in the US, while employment in services went from 14% in 1800 to 76% in 2012 in France, which is close to the change from 13% in 1800 to\n80% in 2012 in the US. Choice C is incorrect because comparing the data for 1900 and 2012 would suggest a similar rate of change in the two\ncountries rather than very different rates: employment in agriculture went from 43% in 1900 to 3% in 2012 in France, which is close to the change\nfrom 41% in 1900 to 2% in 2012 in the US, while employment in services went from 28% in 1900 to 76% in 2012 in France, which is close to the\nchange from 31% in 1900 to 80% in 2012 in the US. Choice D is incorrect because comparing the data for 1800 and 1900 would suggest a similar\nrate of change in the two countries, not very different rates: employment in agriculture went from 64% in 1800 to 43% in 1900 in France, which is\nfairly close to the change from 68% in 1800 to 41% in 1900 in the US, while employment in services went from 14% in 1800 to 28% in 1900 in\nFrance, which is close to the change from 13% in 1800 to 31% in 1900 in the US.",
    "image": "/questions/coeq/sat-coeq-3fc06a91.png",
    "passage": "Rows in table may not add up to 100 due to rounding.\nOver the past two hundred years, the percentage of the population employed in the agricultural sector has declined in both France and the United\nStates, while employment in the service sector (which includes jobs in retail, consulting, real estate, etc.) has risen. However, this transition\nhappened at very different rates in the two countries. This can be seen most clearly by comparing the employment by sector in both countries in\n______",
