    "correctAnswer": "C",
    "explanation": "Choice C is the best answer because it uses data from the graph to effectively complete the example of Eludoyin and his colleagues’ findings\nconcerning female farmers in some regions of Ondo State, Nigeria. The graph presents values for the percentage of Ondo State small-scale\nfarmers who are female, by type of crop and region. The graph shows that of the farmers mainly cultivating non-root vegetables, approximately\n57% in north Ondo and approximately 54% in south Ondo are female; in other words, most of those farmers are female, which exemplifies the\nidea that female farmers make up the majority (more than half) of the farmers cultivating specific types of crops in some regions.\nChoice A is incorrect because it inaccurately cites data from the graph: the graph shows that in south Ondo, most of the farmers mainly\ncultivating non-root vegetables are women (approximately 54%), but that only about 35% (less than half) of the farmers mainly cultivating cereals\nare women. Choice B is incorrect because it inaccurately cites data from the graph: the graph shows that more women in central Ondo mainly\ncultivate cereals than mainly cultivate root crops (approximately 36% and 20%, respectively). Additionally, it doesn’t effectively complete the\nexample because the graph shows that female farmers don’t make up the majority (more than half) of the farmers for any type of crop in central\nOndo. Choice D is incorrect because it doesn’t effectively complete the example; it simply states that a relatively equal proportion of women\nacross the three regions mainly cultivate cereals, which doesn’t address the value for that proportion and thus doesn’t show that a majority\n(more than half) of the farmers cultivating certain crops are female.",
    "image": "/questions/coeq/sat-coeq-403fb4e4.png",
    "passage": "Geographer Adebayo Oluwole Eludoyin and his colleagues surveyed small-scale farmers in three locations in Ondo State, Nigeria—which has\nmountainous terrain in the north, an urbanized center, and coastal terrain in the south—to learn more about their practices, like the types of crops\nthey mainly cultivated. In some regions, female farmers were found to be especially prominent in the cultivation of specific types of crops and\neven constituted the majority of farmers who cultivated those crops; for instance, ______",
