    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it most effectively uses data from the table to complete the statement about the researchers’ conclusion\nabout fossil shark teeth. The text states that mammalian fossil evidence has placed both MFS and PFBV within Hh4 (6 Ma to 4.75 Ma) but “a\nmore precise determination of the sites’ ages has proved challenging,\n” prompting Killingsworth and colleagues to attempt to date the sites by\ncomparing average ⁸⁷Sr/⁸⁶Sr ratios for fossil shark teeth from MFS and PFBV to ratios in the global strontium seawater curve. Given that “⁸⁷Sr/\n⁸⁶Sr ratios in seawater correspond to numerical ages,\n” a fossil whose ⁸⁷Sr/⁸⁶Sr ratio corresponds to the ratio associated with a particular age in\nthe global strontium seawater curve can be inferred to date to that age. According to the table, the ⁸⁷Sr/⁸⁶Sr ratio of 0.709000 for fossil shark\nteeth from MFS corresponds to an age of 5.86 Ma, which falls within Hh4. By contrast, the table shows that the ⁸⁷Sr/⁸⁶Sr ratio of 0.709028 for\nfossils from PFBV would fall between 0.709020 (5.40 Ma) and 0.709040 (4.75 Ma), indicating an age that falls within Hh4 but is more recent\nthan MFS’s age of 5.86 Ma. The data therefore corroborate the conclusion that both sites fall within Hh4 while suggesting that PFBV was likely\ndeposited more recently than MFS was.\nChoice A is incorrect because the table indicates that MFS was deposited closer to the Hh3-Hh4 boundary than PFBV was, not the reverse. The\ntable indicates that PFBV’s ⁸⁷Sr/⁸⁶Sr ratio of 0.709028 corresponds to an age between 4.75 Ma and 5.40 Ma, while MFS’s ⁸⁷Sr/⁸⁶Sr ratio of\n0.709000 corresponds to an age of 5.86 Ma. Because the Hh3-Hh4 boundary occurs at 6 Ma, MFS was deposited closer to that boundary than\nPFBV was. In addition, the text doesn’t establish that mammalian fossil evidence offers less dating precision than ⁸⁷Sr/⁸⁶Sr ratios do; it states\nonly that mammalian fossils have placed both MFS and PFBV in Hh4 and that more precise dating has proved challenging. Choice B is incorrect\nbecause it mischaracterizes the level of support for the site age estimates established through mammalian fossil evidence. The table indicates\nthat the average ⁸⁷Sr/⁸⁶Sr ratios from MFS (0.709000) and PFBV (0.709028) both correspond to ages that fall within Hh4 (6 Ma to 4.75 Ma)—5.86\nMa for MFS and an age between 5.40 Ma and 4.75 Ma for PFBV\n. The ⁸⁷Sr/⁸⁶Sr ratios therefore fully support, rather than only partially support, the\nprevious mammalian fossil evidence placing both sites within Hh4. Choice C is incorrect because the table indicates that the average ⁸⁷Sr/⁸⁶Sr\nratios in fossil shark teeth from MFS (0.709000) and PFBV (0.709028) correspond to different ages—5.86 Ma for MFS and an age between 5.40\nMa and 4.75 Ma for PFBV\n. Because the ratios point to different ages, they don’t support the conclusion that the fossils at the two sites were\ndeposited contemporaneously, or at the same time.",
    "image": "/questions/coeq/sat-coeq-43f4013a.png",
    "passage": "The late Hemphillian (Hh) North American Land Mammal Age includes the subdivisions Hh3, 6.8 million years ago (Ma) to 6 Ma, and Hh4, 6 Ma\nto 4.75 Ma. While mammalian fossils have indicated that Florida’s Montbrook Fossil Site (MFS) and Palmetto Fauna of the Bone Valley Region\n(PFBV) date to Hh4, a more precise determination of the sites’ ages has proved challenging. Stephanie R. Killingsworth et al. compared average\nratios of strontium-87 to strontium-86 (\n87\nSr/\n86\nSr) in fossil shark teeth from MFS and PFBV—0.709000 and 0.709028, respectively—to\n87\nSr/\n86\nSr\nratios in the global strontium seawater curve, a record that shows how\n87\nSr/\n86\nSr ratios in seawater correspond to numerical ages and that is\nused to date fossils and, by extension, fossil sites. The researchers concluded that ______",
    "stem": "Which choice most effectively uses data from the table to complete the statement?"
