    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it accurately uses data from the table to complete the statement about the fibers of three types of sheep.\nThe text discusses some qualities of outer and inner fibers of mouflons, Spanish Merino sheep, and Navajo-Churro sheep and indicates that\nsheep fibers with finer, or smaller, diameters are softer than fibers with larger diameters. The text then sets up a conclusion that can be made by\ncomparing the fibers of all three sheep types. The table shows that the minimum diameter of the Navajo-Churro’s inner fibers is 10 microns,\nwhich is smaller than the minimum diameters of the inner fibers of both the mouflon (15 microns) and the Spanish Merino (17 microns). Thus,\ncomparing the fiber characteristics of all three sheep reveals that at its softest, the inner fiber of the Navajo-Churro is softer than either the\nmouflon’s or the Merino’s inner fiber.\nChoice B is incorrect because it doesn’t accurately describe the data in the table. The table shows that the softness of Navajo-Churro inner fiber\nisn’t uniform (since the diameter of Navajo-Churro inner fiber ranges from 10 microns to 35 microns) and that the diameter of the outer fiber of\nthe mouflon isn’t variable (rather, it is a uniform 150 microns). Choice C is incorrect because it doesn’t accurately describe the data in the table.\nThe text indicates that both Spanish Merino sheep and Navajo-Churro sheep were domesticated from mouflon sheep. The table doesn’t show\nthat domestication increased the minimum diameter of inner fibers for both Spanish Merino sheep and Navajo-Churro sheep from the 15-micron\ndiameter of mouflon inner fibers: the minimum diameter of Spanish Merino increased to 17 microns, but the minimum diameter of Navajo-\nChurro inner fibers decreased to 10 microns. Choice D is incorrect because it doesn’t accurately describe the data in the table. The text explains\nthat sheep fibers with finer, or smaller, diameters are softer than fibers with larger diameters. The table does show that Spanish Merino outer\nfibers are finer, and thus softer, than mouflon outer fibers and that at their finest, Navajo-Churro outer fibers are softer than mouflon outer fibers,\nbut it also shows that Spanish Merino inner fibers are less soft than mouflon inner fibers, since their minimum diameter is greater than 15\nmicrons, and that Navajo-Churro inner fibers can be less soft than mouflon inner fibers, since the diameter ranges up to 35 microns.",
    "image": "/questions/coeq/sat-coeq-4411e15b.png",
    "passage": "Domestic sheep’s wild ancestor, the mouflon, has a coarse outer coat and an inner coat of wool fiber that is finer in diameter and therefore much\nsofter. In some domestic breeds, such as the Spanish Merino, the outer fiber is only marginally coarser than the inner, and the wool is soft\noverall. Thus, Merino wool is ideal for delicate garments worn against the skin. Meanwhile, the Navajo-Churro has been selected to retain the\nmarked distinction between outer and inner fiber that the Merino has lost. Being coarser than Merino wool overall, Navajo-Churro wool yields a\nmore durable yarn, which Diné (Navajo) weavers use in their celebrated rugs. Yet a comparison of the fiber characteristics of all three sheep\nreveals that ______",
