    "correctAnswer": "B",
    "explanation": "Choice B is the best answer because it correctly uses data from the table to illustrate the relationship between orbital and rotational periods\ndescribed in the text. For Earth and each of four TRAPPIST\n-1 exoplanets, the table provides the orbital period and radius (in relation to the radius\nof Earth). The text explains that for each TRAPPIST\n-1 exoplanet, gravitational forces cause the rotational period (how long the planet takes to\nspin once on its axis) to equal the orbital period (how long the planet takes to orbit the star). According to the table, TRAPPIST\n-1e has an orbital\nperiod of 6.1 days. Since the text states that the orbital and rotational periods are equal for these planets, TRAPPIST\n-1e’s rotational period must\nalso be 6.1 days.\nChoice A is incorrect because the table shows that TRAPPIST\n-1e has an orbital period (and thus a rotational period) of 6.1 days, not 1.51 days,\nwhich is the orbital period (and thus the rotational period) of TRAPPIST\n-1b. Furthermore, comparing the length of TRAPPIST\n-1e’s rotational period\nto those of the other exoplanets would not logically complete the example, which should illustrate how the orbital and rotational periods of a\nplanet in TRAPPIST\n-1 are the same length. Choice C is incorrect because the table shows that TRAPPIST\n-1e has an orbital period (and thus a\nrotational period) of 6.1 days, not 9.21 days, which the table shows is the orbital period (and thus rotational period) of TRAPPIST\n-1f. Additionally,\ncomparing the rotational periods of two exoplanets would not logically complete the example, which should illustrate how the orbital and\nrotational periods of a planet in TRAPPIST\n-1 are the same length. Choice D is incorrect because although it correctly identifies TRAPPIST\n-1e’s\norbital period as 6.1 days, it incorrectly states that its rotational period is 0.92 days. This contradicts the text’s statement that the orbital and\nrotational periods are equal for TRAPPIST\n-1 exoplanets. The value 0.92 actually represents TRAPPIST\n-1e’s radius in relation to Earth’s radius, not\nits rotational period.",
    "image": "/questions/coeq/sat-coeq-54be8f96.png",
    "passage": "TRAPPIST\n-1 is a planetary system with a central red dwarf star and several Earth-sized exoplanets. Each planet in this system is so close in orbit\nto the star that the gravitational forces acting between the planet and the star cause the planet’s rotational period around its axis and orbital\nperiod around the star to be equal. For example, the orbital period of TRAPPIST\n-1e is ______",
    "stem": "Which choice most effectively uses data from the table to complete the example?"
