    "difficulty": "hard",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "Resolution makers between the ages of 50 and 64 are more likely to make resolutions related to personal relationships and less likely to make\nresolutions related to finances than resolution makers between the ages of 30 and 49 are."
      },
      {
        "id": "B",
        "text": "Resolution makers between the ages of 18 and 29 are more likely to make resolutions about health and exercise than resolution makers\nbetween the ages of 30 and 49 are."
      },
      {
        "id": "C",
        "text": "The majority of US adults who make resolutions related to health and exercise also make resolutions in multiple additional categories."
      },
      {
        "id": "D",
        "text": "Among all US adults, people become less likely to make New Year’s resolutions as they age, regardless of the type of resolution."
      }
    ],
    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it presents a conclusion about the habits of New Year’s resolution makers that is best supported by\ninformation in the text and the table. The table presents percentages of resolution makers who make particular kinds of resolutions, indexed by\nage bracket. According to the table, 58 percent of resolution makers ages 50 to 64 made resolutions related to personal relationships, compared\nto 53 percent of resolution makers ages 30 to 49—indicating that the older group is more likely to make such resolutions. The table also shows\nthat 56 percent of resolution makers ages 50 to 64 made resolutions related to finances, compared to 63 percent of resolution makers ages 30\nto 49—indicating that the older group is less likely to make financial resolutions. Thus, the data support the conclusion that resolution makers\nbetween the ages of 50 and 64 are more likely to make resolutions related to personal relationships and less likely to make resolutions related to\nfinances than resolution makers between the ages of 30 and 49 are.\nChoice B is incorrect because according to the table, 79 percent of resolution makers ages 18 to 29 made resolutions about health and exercise,\nwhile 80 percent of resolution makers ages 30 to 49 made such resolutions. Therefore, resolution makers ages 18 to 29 are slightly less likely,\nnot more likely, to make resolutions about health and exercise than resolution makers ages 30 to 49 are. Choice C is incorrect because neither\nthe text nor the table provides information about whether resolution makers who make resolutions related to health and exercise also make\nresolutions in multiple additional categories. The text indicates that half of those who make a resolution make more than one, but it doesn’t\nspecify how many or in which categories, and the table presents only the percentages of resolution makers in each age bracket who made\nparticular kinds of resolutions. Choice D is incorrect because the table presents data only about people who chose to make resolutions, not\nabout all US adults; the table therefore can’t support a conclusion about whether US adults overall become less likely to make resolutions as they\nage. Furthermore, although percentages of resolution makers generally decline as age bracket increases in some resolution categories, the table\nshows that the percentage of resolution makers who made health and exercise resolutions remains relatively stable across age brackets; thus,\neven among resolution makers, there isn’t a consistent age-related decline across all types of resolutions.",
    "image": "/questions/coeq/sat-coeq-629fb8a9.png",
    "passage": "A Pew Research Center survey conducted in January 2024 found that three out of ten US adults make at least one New Year’s resolution (a\npromise for the year ahead), while half of those who make a resolution make more than one. The survey asked participants what kinds of\nresolutions they made and separated them into several categories. The table presents percentages of people who make particular kinds of New\nYear’s resolutions among those who choose to make them, indexed by age bracket.\nWhich choice best presents a conclusion about the habits of New Year’s resolution makers that is best supported by information in the text and",
    "stem": "the table?"
