    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it describes data from the graph that support the researchers’ conclusion that there is a growing interest\namong CEOs in connecting with more depar tments in their companies. The graph shows the average number of individuals reporting directly to\nCEOs during three different time periods: the individuals are divided into managers and department leaders. The average number of department\nleaders directly reporting to their CEO during the 1991–1995 period was slightly more than three, during the 1996–2001 period it was four, and\nduring the 2001–2008 period it was almost seven. Thus, the average number of department leaders reporting directly to their CEO rose over the\nthree periods studied, which suggests that CEOs were connecting with more depar tments.\nChoice A is incorrect because the average number of managers and department leaders reporting directly to their CEO rose for both categories\nbetween the 1991–1995 and 2001–2008 periods; thus, it isn’t true that the average numbers didn’t fluctuate. Choice B is incorrect because the\naverage number of managers reporting directly to their CEO was highest in the 2001–2008 period, not in the 1996–2001 period. Choice C is\nincorrect. Although it correctly describes a feature of the graph, the observation that more department leaders than managers are reporting to\nCEOs does not by itself address the question of whether CEOs are connecting with more depar tments over time—to address that question, one\nneeds to know whether the number of department leaders reporting to CEOs is increasing over time.",
    "image": "/questions/coeq/sat-coeq-645fd11a.png",
    "passage": "Considering a large sample of companies, economics experts Maria Guadalupe, Julie Wulf, and Raghuram Rajan assessed the number of\nmanagers and leaders from different depar tments who reported directly to a chief executive officer (CEO). According to the researchers, the\nfindings suggest that across the years analyzed, there was a growing interest among CEOs in connecting with more depar tments in their\ncompanies.",
    "stem": "Which choice best describes data from the graph that support the researchers’ conclusion?"
