    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it most effectively uses data from the table to support the researchers’ conclusion about the harvesting of\nclamshells by Neanderthals for use as tools. The text explains that Neanderthals used clamshells to make tools and that the sturdiest, and\ntherefore the most desirable, shells for this purpose are found on the seafloor, not on the beach. However, the researchers also concluded that\nthe clamshell tools made from shells from the seafloor are rarer than those made from shells from the beach. Meanwhile the table shows that at\neach depth, the number of tools made from shells from the beach exceeds the number made from the more desirable shells from the seafloor.\nThe fact that the more desirable shells are less common suggests that it was significantly more difficult to harvest shells from the seafloor than\nfrom the beach.\nChoice B is incorrect because knowing which depth represents the period of time with the highest Neanderthal population does not help answer\nthe question of why the Neanderthals consistently made more tools from the less desirable shells from the beach than they made from the more\ndesirable shells from the seafloor. Choice C is incorrect because it claims that the beach shells are more durable than the seafloor shells, which\ncontradicts the text’s description of shells from the seafloor as smoother and sturdier than shells from the beach. Choice D is incorrect because\nknowing which depth has the most artifacts or whether the clam population fluctuated does not help explain why tools made from the less\ndesirable shells from the beach outnumber tools made from the more desirable shells from the seafloor.",
    "image": "/questions/coeq/sat-coeq-6a6bbac3.png",
    "passage": "Studying tools unearthed at a cave site on the western coast of Italy, archaeologist Paola Villa and colleagues have determined that prehistoric\nNeanderthal groups fashioned them from shells of clams that they harvested from the seafloor while wading or diving or that washed up on the\nbeach. Clamshells become thin and eroded as they wash up on the beach, while those on the seafloor are smooth and sturdy, so the research\nteam suspects that Neanderthals prized the tools made with seafloor shells. However, the team also concluded that those tools were likely more\nchallenging to obtain, noting that ______",
    "stem": "Which choice most effectively uses data from the table to support the research team’s conclusion?"
