        "text": "Participants with an ignobility score of 5 or less rated admirable-trait candidates as more likable than ignoble-trait candidates, whereas\nparticipants with an ignobility score of 6 or more rated ignoble-trait candidates as equally likable as or even more likable than admirable-trait\ncandidates."
