    "correctAnswer": "C",
    "explanation": "Choice C is the best answer. Electra states that she “knows her own passion,\n” which shows that she’s aware of the intensity of her grief. But she\nalso claims that the “causes are so dire”—meaning the reasons for her grief are so awful—that she can’t let it go, which shows that she believes\nher grief is justified.\nChoice A is incorrect. This quotation doesn’t show that Electra believes her grief is justified. It shows that Electra is aware of its intensity, but it\ndoesn’t suggest that she believes she has a legitimate reason for feeling that way. Choice B is incorrect. This quotation doesn’t show that Electra\nbelieves her grief is justified. It shows that Electra is aware of its intensity, but it doesn’t suggest that she believes she has a legitimate reason for\nfeeling that way. Choice D is incorrect. This quotation doesn’t show that Electra believes her grief is justified. It shows that Electra is aware of the\nintensity of her grief, but it doesn’t suggest that she has a legitimate reason for feeling that way.",
    "passage": "Electra is a circa 420–410 BCE play by Sophocles, translated in 1870 by R.C. Jebb. Electra, who is in mourning for her dead father and her long-\nabsent brother, is aware of the intensity of her grief but believes it to be justified: ______",
    "stem": "Which quotation from Electra most effectively illustrates the claim?"
