    "correctAnswer": "D",
    "explanation": "Choice D is the best answer because it presents a finding that, if true, would most directly support the researchers’ hypothesis about the\nconnection between the dusky shark population decline and the eastern oyster population decline. The text indicates that although dusky sharks\ndon’t usually eat eastern oysters, they do consume cownose rays, which are the main predators of eastern oysters. An increase in the abundance\nof cownose rays in the region in response to a decline in the abundance of dusky sharks would directly support the researchers’ hypothesis: a\nhigher number of cownose rays would consume more eastern oysters, driving down the oyster population.\nChoice A is incorrect because a finding that there’s an association between a decline in the regional abundance of some of dusky sharks’ prey\nand the regional abundance of dusky sharks wouldn’t directly support the researchers’ hypothesis that a decline in dusky sharks has led to a\ndecline in eastern oysters in the region. Although such a finding might help explain why shark abundance has declined, it would reveal nothing\nabout whether the shark decline is related to the oyster decline. Choice B is incorrect because a finding that eastern oyster abundance tends to\nbe greater when dusky sharks and cownose rays are present than when only dusky sharks are present wouldn’t support the researchers’\nhypothesis that a decline in dusky sharks has led to a decline in eastern oysters in the region. The text indicates that the sharks prey on the rays,\nwhich are the main predators of the oysters; if oyster abundance is found to be greater when rays are present than when rays are absent, that\nwould suggest that rays aren’t keeping oyster abundance down, and thus that a decline in rays’ predators, which would be expected to lead to an\nincrease in the abundance of rays, wouldn’t bring about a decline in oyster abundance as the researchers hypothesize. Choice C is incorrect\nbecause a finding that consumption of eastern oysters by cownose rays increased substantially before dusky sharks declined in regional\nabundance wouldn’t support the researchers’ hypothesis that the decline in dusky sharks has led to a decline in eastern oysters in the region.\nSuch a finding would suggest that some factor other than shark abundance led to an increase in rays’ consumption of oysters and thus to a\ndecrease in oyster abundance, thereby weakening the researchers’ hypothesis.",
    "passage": "Researchers hypothesized that a decline in the population of dusky sharks near the mid-Atlantic coast of North America led to a decline in the\npopulation of eastern oysters in the region. Dusky sharks do not typically consume eastern oysters but do consume cownose rays, which are the\nmain predators of the oysters.",
