    "correctAnswer": "B",
    "explanation": "Choice B is the best answer. The claim is that low anger does not negatively affect readers’ perceptions of the review, while high anger does\nnegatively affect readers’ perceptions of the review. This choice accurately expresses the supporting data from the “helpfulness of review” part\nof the graph: that low-anger reviews were rated as slightly more helpful than no-anger reviews, while high-anger reviews were rated as less\nhelpful than no-anger reviews.\nChoice A is incorrect. This choice does not support the conclusion. The conclusion is only about how participants feel about the review itself—\nthe participants’ ratings of the reviewed product are not relevant. Choice C is incorrect. This choice does not support the conclusion. The\nconclusion is only about how participants feel about the review itself—the participants’ attitude towards the reviewed product is not relevant.\nChoice D is incorrect. This choice does not support the conclusion. The conclusion is only about how participants feel about the review itself—\nthe participants’ attitude towards the reviewed product is not relevant.",
    "image": "/questions/coeq/sat-coeq-d5b9ed0d.png",
    "passage": "To understand how expressions of anger in reviews of products affect readers of those reviews, business scholar Dezhi Yin and colleagues\nmeasured study participants’ responses to three versions of the same negative review—a control review expressing no anger, a review\nexpressing a high degree of anger, and a review expressing a low degree of anger. Reviewing the data, a student concludes that the mere\npresence of anger in a review may not negatively affect readers’ perceptions of the review, but a high degree of anger in a review does worsen\nreaders’ perceptions of the review.",
