    "section": "rw",
    "domainId": "info-ideas",
    "domainName": "2. Information and Ideas",
    "subtopicId": "command-of-evidence",
    "subtopic": "Command of evidence",
    "difficulty": "hard",
    "type": "mcq",
    "options": [
      {
        "id": "A",
        "text": "When plants exposed to air from whitefly-free plants were infested, they produced more jasmonic acid than did control plants, whereas when\nplants exposed to air from whitefly-infested plants were infested, they produced less jasmonic acid and more salicylic acid than did control\nplants."
      },
      {
        "id": "B",
        "text": "When plants exposed to air from whitefly-infested plants were infested, they produced less jasmonic acid than salicylic acid, whereas when\nplants exposed to air from whitefly-free plants were infested, they produced about the same amount of jasmonic acid and salicylic acid."
      },
      {
        "id": "C",
        "text": "When plants exposed to air from whitefly-free plants were infested, they produced both jasmonic acid and salicylic acid, whereas when plants\nexposed to air from whitefly-infested plants were infested, they exclusively produced salicylic acid."
      },
      {
        "id": "D",
        "text": "When plants exposed to air from whitefly-infested plants were infested, they produced less jasmonic acid than did control plants, whereas\nwhen plants exposed to air from whitefly-free plants were infested, they produced more jasmonic acid and salicylic acid than did control\nplants."
      }
    ],
    "correctAnswer": "A",
    "explanation": "Choice A is the best answer because it best describes data from the graph that support the researchers’ conclusion about whitefly-induced\ndefenses in tomato plants. According to the text, tomato plants produce airborne chemicals that prompt nearby tomato plants to increase their\nproduction of appropriate defensive chemicals, such as jasmonic acid in response to herbivory and salicylic acid in response to microbial\ninfection. The text goes on to indicate that researchers concluded that whiteflies induce tomato plants to emit chemicals that cause nearby\nplants to defend against microbial infection instead of herbivory from whiteflies. The graph shows that control tomato plants (plants that weren’t\nexposed to any chemicals from nearby tomato plants and weren’t subsequently infested with whiteflies) produced about 140 nanograms of\njasmonic acid per gram of dry weight and about 120 nanograms of salicylic acid per gram of dry weight, which indicates the baseline levels of\nthese defensive chemicals in tomato plants. The graph also shows that plants exposed to air from whitefly-free plants produced about 205\nnanograms of jasmonic acid per gram of dry weight when subsequently infested by whiteflies, which is more than the amount produced by the\ncontrol plants. This suggests that when infested with whiteflies, tomato plants that weren’t previously exposed to air from nearby whitefly-\ninfested plants begin producing higher levels of jasmonic acid to defend against the infestation. Finally, the graph also shows that plants\nexposed to air from whitefly-infested plants and then subsequently infested by whiteflies produced approximately 100 nanograms of jasmonic\nacid per gram of dry weight (which is less than control plants did) and approximately 175 nanograms of salicylic acid per gram of dry weight\n(which is more than control plants did). This suggests that whiteflies cause tomato plants to emit chemical signals that decrease nearby plants’\ndefenses against whitefly herbivory relative to baseline levels and redirect their defenses toward microbial infection, thereby supporting the\nresearchers’ conclusion that whiteflies cause tomato plants to emit airborne chemical signals that induce nearby plants to preferentially defend\nagainst microbes even when experiencing herbivory from whiteflies.\nChoice B is incorrect. Although the graph shows that tomato plants exposed to whitefly-infested plants produced less jasmonic acid than\nsalicylic acid (about 100 nanograms of jasmonic acid per gram of dry weight vs. about 175 nanograms of salicylic acid per gram of dry weight),\nand although this might suggest that those plants are therefore better defended against microbial attack than against herbivory, this wouldn’t be\nsufficient to conclude that this is the case: without reference to the relative levels of defensive chemicals produced by the plants in the other\nexperimental conditions, it would be impossible to conclude that exposure to air from whitefly-infested plants either induces or diminishes these\nplants’ defenses to different kinds of threats. Furthermore, the graph shows that plants exposed to air from whitefly-free plants produced about\n205 nanograms of jasmonic acid per gram of dry weight and about 130 nanograms of salicylic acid per gram of dry weight, not that they\nproduced the same amount of the two acids. Choice C is incorrect because it inaccurately describes the data in the graph. The graph shows that\nplants in all three conditions produced both jasmonic and salicylic acid, not that plants exposed to air from whitefly-infested plants produce no\njasmonic acid at all. Choice D is incorrect. Although the graph shows that plants exposed to air from whitefly-infested plants produced about 100\nnanograms of jasmonic acid per gram of dry weight when infested, which is less than the amount produced by control plants (about 140\nnanograms per gram of dry weight), and although the graph shows that plants exposed to air from whitefly-free plants produced about 205\nnanograms of jasmonic acid per gram of dry weight when infested (which is more than the amount produced by control plants) and about 130\nnanograms of salicylic acid per gram of dry weight (which is more than the approximately 120 nanograms per gram of dry weight produced by\ncontrol plants), this wouldn’t support the researchers’ conclusion that plants exposed to air from whitefly-infested plants preferentially defend\nagainst microbial infection—that is, that they increase their levels of salicylic acid and decrease their levels of jasmonic acid relative to control\nplants. Rather, the data would suggest that exposure to air from whitefly-infested plants reduces plants’ defenses against herbivory, but these\ndata wouldn’t indicate that whiteflies induce plants to redirect their defenses to guard against microbial infection. Furthermore, the data\nconcerning plants exposed to air from whitefly-free plants merely indicate that these plants increase their defenses against both herbivory and\nmicrobial infection when infested by whiteflies.",
    "image": "/questions/coeq/sat-coeq-d5da74be.png",
    "passage": "In tomato plants, herbivory induces defensive production of jasmonic acid, while microbial infection induces defensive production of salicylic\nacid; plants also emit airborne chemicals to initiate the appropriate defense in nearby tomato plants. Researchers investigated the poor\nresistance tomato plants show to whitefly herbivory by exposing some plants to airborne chemicals from whitefly-free plants and others to\nairborne chemicals from whitefly-infested plants, then infesting both groups of plants with whiteflies. The researchers concluded that whiteflies\ninduce tomato plants to emit chemicals that cause other tomato plants to preferentially defend against microbial infection even when under\nherbivorous attack.",
    "stem": "Which choice best describes data from the graph that support the researchers’ conclusion?"
